Cpu cpu(){Cpu c{};for(unsigned i=0;i<sizeof c;++i)reinterpret_cast<unsigned char *>(&c)[i]=random_word();set32(c.r[4],car);set32(c.r[28],gp);set32(c.r[29],sp);set32(c.r[31],0x123456);c.pc=0x1e6d48;c.budget=entry_budget;return c;}
