 std::vector<unsigned char> expected_ram;if(!ram.empty())expected_ram.assign(g_ram,g_ram+kRamSize);
 if(!ram.empty())std::memcpy(g_ram,ram.data(),ram.size());else {std::memcpy(g_ram+car,object.data(),object.size());std::memcpy(g_ram+sp-128,stack.data(),128);}
